      "lectureId": 4,
      "lectureTitle": "영양소의 흡수",
      "hasWiki": true,
      "bee": false,
      "exact": false,
      "question": "위 평활근의 기록 A와 B에서 slow-wave 빈도는 같지만, 각 정점의 spike potential 수는 B가 더 많다. 옳은 설명을 모두 포함한 조합은?",
      "passage": "I. Equal slow-wave frequencies do not require equal contraction strengths.\nII. Every slow wave produces a maximal contraction even if the membrane does not reach spike threshold.\nIII. The additional spikes in B can increase Ca2+ entry and contractile force.",
      "choices": [
        "I",
        "I, II",
        "I, III",
        "II, III",
        "I, II, III"
      ],
      "answerIndices": [
        3
      ],
      "multiple": false,
      "images": [],
      "points": 1,
      "modelAnswer": "",
      "explanation": "I. 옳다. Slow wave는 수축이 일어날 리듬을 제공한다. 빈도가 같아도 spike와 신경·호르몬 입력이 달라 수축력은 다를 수 있다. II. 틀리다. 역치에 이르지 않은 파형까지 최대수축을 만들지는 않는다. Slow wave 하나와 최대수축 하나를 동일시하지 않는다. III. 옳다. 역치를 넘는 spike가 증가하면 Ca²⁺ 유입과 수축력 증가로 연결될 수 있다. 빈도와 강도를 나누어 읽는다.",
      "reconstructed": false,
      "examOverride": false,
      "section": "느린파와 Cajal 사이질세포",
      "originalAuthored": true,
      "origin": "신규 출제",
