      "hasWiki": true,
      "bee": false,
      "exact": false,
      "question": "아침 식사 직후 변의를 느꼈다. 옳은 설명을 모두 포함한 조합은?",
      "passage": "I. The timing proves that the newly eaten breakfast has already traversed the entire intestine and become stool.\nII. Gastrocolic and duodenocolic reflexes can promote colonic mass movements.\nIII. Movement of pre-existing colonic contents into the rectum can account for the urge.",
      "choices": [
        "I",
        "I, II",
        "I, III",
        "II, III",
        "I, II, III"
      ],
      "answerIndices": [
        4
      ],
      "multiple": false,
      "images": [],
      "points": 1,
      "modelAnswer": "",
      "explanation": "I. 틀리다. 반사 반응이 빨리 일어나는 것과 새 음식이 소화관 전체를 통과하는 것은 다른 시간 과정이다. II. 옳다. 식후 위·십이지장 자극이 대장의 mass movement를 촉진할 수 있다. III. 옳다. 이미 대장에 있던 내용물이 직장으로 들어와 팽창시키면 배변 욕구가 생긴다. 방금 먹은 음식이 곧바로 대변이 된다는 해석은 필요 없다.",
      "reconstructed": false,
