      "modelAnswer": "",
      "explanation": "출제자의 요청에 따라 강의록에 없는 내용을 출제하였다. 저삼투압 ORS의 표준 조성에서 trisodium citrate dihydrate는 2.9 g/L이다. 포도당·Na⁺ 공동수송 원리만으로는 이 배합 수치를 도출할 수 없다.",
