      "hasWiki": true,
      "bee": false,
      "exact": false,
      "question": "담즙산 재흡수율이 95%에서 80%로 감소하였다. 한 순환 동안 장으로 분비되는 양은 같으며, 보상성 변화는 계산에서 제외한다. 옳은 설명을 모두 포함한 조합은?",
      "passage": "I. Fecal loss during that cycle increases from 5% to 20% of the secreted amount.\nII. Fecal loss during that cycle increases only 1.2-fold.\nIII. The calculation proves that hepatic synthesis has already increased fourfold.",
      "choices": [
        "I",
        "I, II",
        "I, III",
        "II, III",
        "I, II, III"
      ],
      "answerIndices": [
        1
      ],
      "multiple": false,
      "images": [],
      "points": 1,
      "modelAnswer": "",
      "explanation": "I. 옳다. 소실률은 재흡수율의 나머지이므로 5%에서 20%로 바뀐다. II. 틀리다. 같은 분비량에서 20/5=4배이다. 재흡수율의 비와 소실량의 비를 혼동하지 않는다. III. 틀리다. 한 회차의 질량수지 계산은 간의 실제 보상 정도를 측정한 결과가 아니다. 간 합성이 이미 4배 늘었다고 결론 낼 수 없다.",
      "reconstructed": false,
