      "multiple": false,
      "images": [],
      "points": 1,
      "modelAnswer": "",
      "explanation": "I. 옳다. Mass movement가 직장으로 내용물을 전달하는 것이 시작 사건이 될 수 있다. II. 옳다. 유입된 내용물의 팽창 자극이 감각 입력과 배변 욕구·반사로 이어진다. III. 옳다. 감각 자극이 생기는 것과 실제 배변을 완수하는 것은 별개다. 항문괄약근과 골반저의 협응도 필요하다.",
